using UnityEngine;
using UnityEngine.InputSystem;
namespace Rekindle {
 public sealed class GameHUD:MonoBehaviour {
  [SerializeField]Session session;GUIStyle label,title,small,button,panel;Texture2D white;int selectedSlot=-1;Rect bagRect=new Rect(275,115,730,465),restoreRect=new Rect(350,165,580,360);bool styles;
  public void Configure(Session s){session=s;}
  void Init(){if(styles)return;styles=true;white=Texture2D.whiteTexture;label=new GUIStyle(GUI.skin.label){fontSize=18,wordWrap=true,normal={textColor=new Color(.92f,.88f,.76f)}};title=new GUIStyle(label){fontSize=32,fontStyle=FontStyle.Bold};small=new GUIStyle(label){fontSize=14};button=new GUIStyle(GUI.skin.button){fontSize=17,wordWrap=true,normal={textColor=new Color(1,.85f,.5f)},padding=new RectOffset(10,10,8,8)};panel=new GUIStyle(GUI.skin.box){normal={background=white,textColor=Color.white}};}
  void Box(Rect r,Color color){var old=GUI.color;GUI.color=color;GUI.DrawTexture(r,white);GUI.color=old;}
  void Frame(Rect r){Box(new Rect(r.x-2,r.y-2,r.width+4,r.height+4),new Color(.57f,.43f,.23f,.95f));Box(r,new Color(.045f,.075f,.09f,.96f));}
  void Text(Rect r,string t,GUIStyle style=null){GUI.Label(r,t,style??label);}
  bool Button(Rect r,string t)=>GUI.Button(r,t,button);
  void Bar(Rect r,float value,float max,Color c,string text){Box(r,new Color(.04f,.04f,.05f,.95f));Box(new Rect(r.x+2,r.y+2,(r.width-4)*Mathf.Clamp01(value/max),r.height-4),c);Text(new Rect(r.x+8,r.y,r.width,r.height),text,small);}
  void Update(){if(!session||Mouse.current==null)return;Vector2 p=Mouse.current.position.ReadValue();p=new Vector2(p.x/Screen.width*1280,(Screen.height-p.y)/Screen.height*720);session.Orbit.PointerOverUI=session.Menu||session.Paused||session.InventoryOpen||session.Inspected||p.y>618||new Rect(15,15,300,105).Contains(p);}
  void OnGUI(){if(!session||session.Player.Health==null)return;Init();GUI.matrix=Matrix4x4.TRS(Vector3.zero,Quaternion.identity,new Vector3(Screen.width/1280f,Screen.height/720f,1));if(session.Menu){MainMenu();return;}Frame(new Rect(20,20,280,96));Text(new Rect(35,24,250,26),"THE UNFADING EMBER");Bar(new Rect(35,55,250,22),session.Player.Health.Value,session.Player.Health.Max,new Color(.64f,.2f,.18f),"Health  "+Mathf.CeilToInt(session.Player.Health.Value)+" / "+session.Player.Health.Max);Bar(new Rect(35,82,250,18),session.Player.Energy.Value,100,new Color(.18f,.5f,.58f),"Energy  "+Mathf.CeilToInt(session.Player.Energy.Value));
   Frame(new Rect(840,20,420,130));Text(new Rect(860,30,380,26),session.World.Complete?"CINDERHOLLOW REKINDLED":"A VALLEY THAT REMEMBERS");Text(new Rect(860,62,380,76),session.World.Objective,small);
   var target=session.Combat.Target;if(target&&target.Alive){Frame(new Rect(465,24,350,67));Text(new Rect(480,28,320,25),target.Title);Bar(new Rect(480,60,320,18),target.Health.Value,target.Health.Max,new Color(.6f,.22f,.4f),Mathf.CeilToInt(target.Health.Value)+" / "+target.Health.Max);}
   Text(new Rect(25,132,330,60),Region()+"\n"+(session.Equipment.Improved?"Dawn Blade : Forged by Mira":"Traveller's Blade"),small);
   if(session.Nearest&&!session.InventoryOpen&&!session.Inspected){Frame(new Rect(380,555,520,48));Text(new Rect(398,566,485,30),"[ F / Right-click ]  "+session.Nearest.Title);}
   string[] names={"Strike","Ember\nCleave","Evade","Wildfruit","Inventory","Hearth"};string[] costs={"Melee","30 energy","22 energy","Heal 45","I","At home"};for(int i=0;i<6;i++){Rect r=new Rect(370+i*90,626,82,67);Frame(r);if(Button(r,(i+1)+"  "+names[i]))session.Action(i);Text(new Rect(r.x,r.y+70,90,20),costs[i],small);}
   Text(new Rect(20,648,330,65),"W/S move : A/D turn : Q/E strafe\nLMB orbit : RMB steer : Tab target\nSpace evade : F interact : Esc menu",small);
   if(Time.unscaledTime<session.MessageUntil){Frame(new Rect(300,470,680,72));Text(new Rect(315,481,650,62),session.Message);}
   if(!session.Player.Alive){Frame(new Rect(420,270,440,110));Text(new Rect(440,290,400,70),"Your ember endures.\nReturning to the hearth:",title);}
   if(session.InventoryOpen)Inventory();if(session.Inspected)Restoration();if(session.Paused)Pause();DrawLabels();
  }
  string Region(){var p=session.Player.transform.position;return p.z>115?"THE SUNKEN SANCTUARY":p.z>65?"ASHEN APPROACH":p.z>25?"THE WHISPERWOOD":"CINDERHOLLOW";}
  void MainMenu(){Frame(new Rect(75,95,485,525));Text(new Rect(110,130,415,65),"R E K I N D L E",title);Text(new Rect(110,200,405,130),"A valley broken. A fire remembered.\n\nBring a lost community home, one place and one soul at a time.");if(Button(new Rect(110,365,405,48),"Begin journey"))session.Begin(false);GUI.enabled=session.Saves.Exists;if(Button(new Rect(110,425,405,48),"Continue"))session.Begin(true);GUI.enabled=true;Text(new Rect(110,500,405,95),"CINDERHOLLOW : A restoration story\nCursor-first third-person exploration\nWindows PC : Keyboard and mouse",small);Text(new Rect(815,570,380,100),":This place exists differently\nbecause of what I did.:",title);}
  void Inventory(){Frame(bagRect);Text(new Rect(300,130,630,45),"SATCHEL & EQUIPMENT",title);if(Button(new Rect(940,130,40,35),":"))session.ClosePanel();Text(new Rect(300,185,660,45),"Equipped: "+(session.Equipment.Improved?"Dawn Blade (+50% strike damage)":"Traveller's Blade")+"\nClick two occupied slots to swap. Click wildfruit to eat.",small);for(int i=0;i<16;i++){int col=i%8,row=i/8;Rect r=new Rect(300+col*83,255+row*95,76,85);Frame(r);if(i<session.Bag.Slots.Count){var s=session.Bag.Slots[i];var def=session.Item(s.id);Box(new Rect(r.x+26,r.y+10,24,24),def?def.tint:Color.yellow);if(Button(r,"\n"+session.ItemTitle(s.id)+"\n:"+s.quantity)){if(s.id=="food")session.UseFood();else if(selectedSlot<0)selectedSlot=i;else{session.Bag.Swap(selectedSlot,i);selectedSlot=-1;session.Save();}}if(r.Contains(Event.current.mousePosition)&&def)Text(new Rect(300,465,660,65),def.description,small);}}Text(new Rect(300,540,660,25),session.Bag.Slots.Count+" / 16 stacks : "+(selectedSlot>=0?"Select destination slot":"Materials restore places; anchors restore people"),small);}
  void Restoration(){var b=session.Inspected;Frame(restoreRect);Text(new Rect(375,185,480,45),b.Title,title);if(Button(new Rect(865,185,40,35),":"))session.ClosePanel();int stage=session.World.Stage(b.Id);Text(new Rect(375,240,505,55),stage==0?"RUINED ? STABILIZED":stage==1?"STABILIZED ? RESTORED":"RESTORED : A place returned to the living");Text(new Rect(375,300,505,55),b.Detail,small);string req="";foreach(var c in session.World.Cost(b.Id))req+=session.ItemTitle(c.id)+"  "+session.Bag.Count(c.id)+" / "+c.quantity+"    ";Text(new Rect(375,365,505,55),req);string block=session.World.Block(b.Id);Text(new Rect(375,420,505,45),block,small);GUI.enabled=stage<2&&block=="";if(Button(new Rect(375,467,505,40),"Restore this place"))session.RestoreBuilding();GUI.enabled=true;if(stage==2&&Button(new Rect(375,467,505,40),b.Id=="garden"?"Gather first harvest":b.Id=="hearth"?"Rest at the hearth":b.Id=="forge"?"Visit Mira":"Remember what changed"))session.UseBuildingService();}
  void Pause(){Frame(new Rect(430,180,420,360));Text(new Rect(460,210,350,50),"THE EMBER RESTS",title);if(Button(new Rect(460,285,360,45),"Resume"))session.TogglePause();if(Button(new Rect(460,345,360,45),"Save journey")){session.Save();session.Notify("Journey saved");}if(Button(new Rect(460,405,360,45),"Save and quit")){session.Save();Application.Quit();}Text(new Rect(460,475,360,40),"Restoration is saved after each milestone.",small);}
  void DrawLabels(){if(session.Menu||session.Paused)return;var target=session.Combat.Target;if(target&&target.Alive){var p=Camera.main.WorldToScreenPoint(target.transform.position+Vector3.up*2.8f);if(p.z>0)Text(new Rect(p.x/Screen.width*1280-70,(Screen.height-p.y)/Screen.height*720,160,30),"? "+target.Title,small);}}
 }
}
